style.css:
/* Abyss After Dark — madeinabyssmangaonline.com */

/* Swap these colors if you want a different atmosphere */
:root {
  --my-bg: #111820;
  --my-surface: #1C2930;
  --my-surface-hover: #263941;
  --my-text: #E0E8E7;
  --my-muted: #A6B5B8;
  --my-accent: #76C9C0;
  --my-border: #34474D;
}

/* Main dark background and typography */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: "Segoe UI", sans-serif !important;
  line-height: 1.65 !important;
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
  color: var(--my-text) !important;
  letter-spacing: 0.3px !important;
}

/* Paragraphs and descriptions */
p {
  color: var(--my-muted) !important;
}

/* Links and chapter titles */
a {
  color: var(--my-accent) !important;
  text-decoration: none !important;
  transition: color 0.2s ease !important;
}

a:hover {
  color: #B0F0E9 !important;
  text-decoration: underline !important;
}

/* Buttons */
button {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 8px !important;
  transition: background 0.2s ease !important;
}

button:hover {
  background: var(--my-surface-hover) !important;
}

/* Manga artwork */
img {
  border-radius: 5px !important;
}

/* Form elements */
input,
select,
textarea {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 6px !important;
}

/* Text selection */
::selection {
  background: #367D79 !important;
  color: #FFFFFF !important;
}
